 1 │ package hu.bankmonitor.payments.accounts;
 2 │ 
 3 │ import java.util.Objects;
 4 │ 
 5 │ /**
 6 │  * The two Accounts a Transfer touches, named by their role in it and locked for the rest
 7 │  * of the transaction that asked for them.
 8 │  *
 9 │  * <p>The order they were locked in is deliberately not recoverable from here. It is a
10 │  * property of the acquisition (design decision 6) and no business of the caller, which
11 │  * reads the source to check its Available Balance and credits the destination regardless
12 │  * of which of the two the database happened to see first.
13 │  *
14 │  * <p>Valid only inside that transaction: once it ends the locks are released and these
15 │  * become detached entities whose balances anyone may already have changed.
16 │  */
17 │ public record LockedAccounts(Account source, Account destination) {
18 │ 
19 │ 	public LockedAccounts {
20 │ 		Objects.requireNonNull(source, "a transfer has a source account");
21 │ 		Objects.requireNonNull(destination, "a transfer has a destination account");
22 │ 	}
23 │ }
===== src/main/java/hu/bankmonitor/payments/accounts/AccountRepository.java
 1 │ package hu.bankmonitor.payments.accounts;
 2 │ 
 3 │ import jakarta.persistence.LockModeType;
 4 │ import org.springframework.data.jpa.repository.Lock;
 5 │ import org.springframework.data.repository.Repository;
 6 │ 
 7 │ import java.util.List;
 8 │ import java.util.Optional;
 9 │ 
10 │ import static jakarta.persistence.LockModeType.PESSIMISTIC_WRITE;
11 │ 
12 │ /**
13 │  * Persistence for {@link Account}, package-private so that reaching it from another slice
14 │  * does not compile (design decision 30).
15 │  *
16 │  * <p>It extends the bare {@link Repository} marker rather than {@code CrudRepository},
17 │  * which declares nothing, so every method here has a call site today. {@code CrudRepository}
18 │  * would hand the slice {@code delete}, {@code deleteAll} and a lookup by id before anything
19 │  * asks for them — and a repository whose surface is larger than its use is a set of
20 │  * signatures guessed rather than designed. Ticket 12's ascending-ID locking query arrives
21 │  * with its own.
22 │  */
23 │ interface AccountRepository extends Repository<Account, Long> {
24 │ 
25 │ 	/**
26 │ 	 * Every Account, oldest first. The order is part of the listing's contract rather than
27 │ 	 * a detail of the query: without it the accounts screen may reshuffle itself between
28 │ 	 * two refetches of data that has not changed.
29 │ 	 */
30 │ 	List<Account> findAllByOrderByIdAsc();
31 │ 
32 │ 	/** Writes one Account, which is how an Account comes to exist. */
33 │ 	Account save(Account account);
34 │ 
35 │ 	/**
36 │ 	 * Writes several Accounts in one transaction, which is what the demo seeding of
37 │ 	 * {@link DemoAccountSeeder} needs and all it needs — a half-seeded application is a
38 │ 	 * worse starting point than an empty one.
39 │ 	 */
40 │ 	List<Account> saveAll(Iterable<Account> accounts);
41 │ 
42 │ 	/**
43 │ 	 * Reads one Account and holds a row lock on it until the surrounding transaction ends,
44 │ 	 * so no other transaction can read-for-update or write that row in the meantime.
45 │ 	 *
46 │ 	 * <p>{@link LockModeType#PESSIMISTIC_WRITE} is what turns the {@code select} into a
47 │ 	 * {@code select … for update}. Call it through {@link AccountLocking} rather than
48 │ 	 * directly: on its own it says nothing about the order two of them are taken in, and
49 │ 	 * the order is the entire deadlock argument of design decision 6.
50 │ 	 */
51 │ 	@Lock(PESSIMISTIC_WRITE)
52 │ 	Optional<Account> findAndLockById(long accountId);
53 │ }
===== src/main/java/hu/bankmonitor/payments/accounts/AccountService.java
 1 │ package hu.bankmonitor.payments.accounts;
 2 │ 
 3 │ import hu.bankmonitor.payments.common.Money;
 4 │ import org.springframework.stereotype.Service;
 5 │ import org.springframework.transaction.annotation.Transactional;
 6 │ 
 7 │ import java.util.List;
 8 │ 
 9 │ /**
10 │  * What the accounts slice can be asked to do, and where the transaction around it starts.
11 │  *
12 │  * <p>Design decision 30 forbids a controller holding a repository — asserted by
13 │  * {@code ModuleBoundariesHoldTest} — because a controller that reaches persistence
14 │  * directly has skipped the layer that owns the transaction. Today the work either side of
15 │  * that boundary is one call each way; the moment ticket 13 reserves against an Account
16 │  * there will be more.
17 │  *
18 │  * <p>The class is package-private and the methods are public, which looks backwards and is
19 │  * not: proxy-based AOP silently ignores {@code @Transactional} on a non-public method, so a
20 │  * demotion here would leave a method that reads as transactional and is not, with no error
21 │  * to read (design decision 30).
22 │  */
23 │ @Service
24 │ class AccountService {
25 │ 
26 │ 	private final AccountRepository accounts;
27 │ 
28 │ 	AccountService(AccountRepository accounts) {
29 │ 		this.accounts = accounts;
30 │ 	}
31 │ 
32 │ 	/** Every Account there is. Design decision 31 declines pagination; this is all of them. */
33 │ 	@Transactional(readOnly = true)
34 │ 	public List<Account> listAll() {
35 │ 		return accounts.findAllByOrderByIdAsc();
36 │ 	}
37 │ 
38 │ 	/**
39 │ 	 * Opens an Account holding the given amount, in the currency that amount is
40 │ 	 * denominated in, and returns it with the identifier the database gave it.
41 │ 	 */
42 │ 	@Transactional
43 │ 	public Account open(Money openingBalance) {
44 │ 		return accounts.save(new Account(openingBalance));
45 │ 	}
46 │ }

