 53 │ 	@GeneratedValue(strategy = GenerationType.IDENTITY)
 54 │ 	private Long id;
 55 │ 
 56 │ 	private Long sourceAccountId;
 57 │ 
 58 │ 	private Long destinationAccountId;
 59 │ 
 60 │ 	@Embedded
 61 │ 	@AttributeOverride(name = "minorUnits", column = @Column(name = "debited_amount_minor_units"))
 62 │ 	@AttributeOverride(name = "currency", column = @Column(name = "debited_amount_currency"))
 63 │ 	private Money debitedAmount;
 64 │ 
 65 │ 	@Embedded
 66 │ 	@AttributeOverride(name = "minorUnits", column = @Column(name = "credited_amount_minor_units"))
 67 │ 	@AttributeOverride(name = "currency", column = @Column(name = "credited_amount_currency"))
 68 │ 	private Money creditedAmount;
