 91 │ 			Money debitedAmount, Money creditedAmount, Instant requestedAt) {
 92 │ 		this.sourceAccountId = Objects.requireNonNull(sourceAccountId, "a transfer leaves an account");
 93 │ 		this.destinationAccountId = Objects.requireNonNull(destinationAccountId, "a transfer arrives somewhere");
 94 │ 		this.debitedAmount = Objects.requireNonNull(debitedAmount, "a transfer moves an amount");
 95 │ 		this.creditedAmount = Objects.requireNonNull(creditedAmount, "a transfer credits an amount");
 96 │ 		this.createdAt = Objects.requireNonNull(requestedAt, "a transfer happens at a time");
 97 │ 		this.status = TransferStatus.PENDING;
 98 │ 	}
