106 │ 		return sourceAccountId;
107 │ 	}
108 │ 
109 │ 	/** The Account the money arrives at, credited only at settlement. */
110 │ 	public Long getDestinationAccountId() {
111 │ 		return destinationAccountId;
112 │ 	}
113 │ 
114 │ 	/** What leaves the source Account, in the source Account's currency. */
115 │ 	public Money getDebitedAmount() {
116 │ 		return debitedAmount;
117 │ 	}
118 │ 
119 │ 	/** What reaches the destination Account, in the destination Account's currency. */
120 │ 	public Money getCreditedAmount() {
121 │ 		return creditedAmount;
122 │ 	}
123 │ 
124 │ 	public TransferStatus getStatus() {
125 │ 		return status;
126 │ 	}
127 │ 
128 │ 	/** When the Transfer was requested. The Transactions list is ordered on it. */
129 │ 	public Instant getCreatedAt() {
130 │ 		return createdAt;
131 │ 	}
132 │ }
