 1 │ package hu.bankmonitor.payments.common;
 2 │ 
 3 │ import jakarta.persistence.Embeddable;
 4 │ import jakarta.persistence.EnumType;
 5 │ import jakarta.persistence.Enumerated;
 6 │ import org.hibernate.annotations.JdbcTypeCode;
 7 │ import org.hibernate.type.SqlTypes;
 8 │ 
 9 │ import java.util.Objects;
10 │ 
11 │ /**
12 │  * An amount of money: a whole count of {@link Currency}'s Minor Units, paired with the
13 │  * currency it is denominated in.
14 │  *
15 │  * <p>There is no bare amount in this context. A number on its own is not money, which is
16 │  * why the currency is a component of the value rather than a column beside it.
17 │  */
18 │ @Embeddable
19 │ public record Money(
20 │ 		long minorUnits,
21 │ 
22 │ 		// Left unannotated, JPA stores the currency by ordinal. See design decision 29.
23 │ 		@Enumerated(EnumType.STRING) @JdbcTypeCode(SqlTypes.VARCHAR) Currency currency) {
24 │ 
25 │ 	public Money {
26 │ 		Objects.requireNonNull(currency, "an amount with no currency is not money");
27 │ 	}
28 │ 
29 │ 	/** No money at all, in a stated currency — a new Account's Reserved Amount, for one. */
30 │ 	public static Money zero(Currency currency) {
31 │ 		return new Money(0L, currency);
32 │ 	}
33 │ 
34 │ 	/**
35 │ 	 * @throws IllegalArgumentException if the addend is in a different currency
36 │ 	 * @throws ArithmeticException if the sum does not fit in a {@code long}
37 │ 	 */
38 │ 	public Money plus(Money addend) {
39 │ 		return new Money(Math.addExact(minorUnits, minorUnitsMatching(addend)), currency);
40 │ 	}
41 │ 
42 │ 	/**
43 │ 	 * @throws IllegalArgumentException if the subtrahend is in a different currency
44 │ 	 * @throws ArithmeticException if the difference does not fit in a {@code long}
45 │ 	 */
46 │ 	public Money minus(Money subtrahend) {
47 │ 		return new Money(Math.subtractExact(minorUnits, minorUnitsMatching(subtrahend)), currency);
48 │ 	}
49 │ 
50 │ 	/**
51 │ 	 * Whether this is strictly the smaller amount. An Available Balance equal to the
52 │ 	 * amount requested is enough to cover it, so the overdraft check reads
53 │ 	 * {@code available.isLessThan(amount)}.
54 │ 	 *
55 │ 	 * <p>Deliberately a named method rather than {@link Comparable}, whose {@code compareTo}
56 │ 	 * has to be total and so could not refuse a cross-currency comparison.
57 │ 	 *
58 │ 	 * @throws IllegalArgumentException if the other amount is in a different currency
59 │ 	 */
60 │ 	public boolean isLessThan(Money other) {
61 │ 		return minorUnits < minorUnitsMatching(other);
62 │ 	}
63 │ 
64 │ 	/**
65 │ 	 * The other amount's Minor Units, once it is established that they count the same
66 │ 	 * thing as this one's.
67 │ 	 *
68 │ 	 * <p>Mixing currencies is a bug in the caller rather than something a user asked for,
69 │ 	 * so it is an unchecked exception and nothing catches it: two amounts meet only after
70 │ 	 * a conversion has made them one currency.
71 │ 	 */
72 │ 	private long minorUnitsMatching(Money other) {
73 │ 		if (currency != other.currency) {
74 │ 			throw new IllegalArgumentException(
75 │ 					"%s and %s are different currencies; one has to be converted first"
76 │ 							.formatted(currency, other.currency));
77 │ 		}
78 │ 		return other.minorUnits;
79 │ 	}
80 │ }

