68 │ 	 * <p>Mixing currencies is a bug in the caller rather than something a user asked for,
69 │ 	 * so it is an unchecked exception and nothing catches it: two amounts meet only after
70 │ 	 * a conversion has made them one currency.
71 │ 	 */
72 │ 	private long minorUnitsMatching(Money other) {
73 │ 		if (currency != other.currency) {
74 │ 			throw new IllegalArgumentException(
75 │ 					"%s and %s are different currencies; one has to be converted first"
76 │ 							.formatted(currency, other.currency));
77 │ 		}
78 │ 		return other.minorUnits;
79 │ 	}
80 │ }

