  1 │ package hu.bankmonitor.payments.accounts;
  2 │ 
  3 │ import hu.bankmonitor.payments.common.Currency;
  4 │ import hu.bankmonitor.payments.common.Money;
  5 │ import org.junit.jupiter.api.DisplayName;
  6 │ import org.junit.jupiter.api.Test;
  7 │ 
  8 │ import java.util.ArrayList;
  9 │ import java.util.HashMap;
 10 │ import java.util.List;
 11 │ import java.util.Map;
 12 │ import java.util.Optional;
 13 │ 
 14 │ import static org.assertj.core.api.Assertions.assertThat;
 15 │ import static org.assertj.core.api.Assertions.assertThatThrownBy;
 16 │ 
 17 │ /**
 18 │  * The ordering rule of design decision 6, asserted where it is decidable: which Account
 19 │  * {@link AccountLocking} asks for first, and that the answer never depends on which one
 20 │  * the Transfer is moving money out of.
 21 │  *
 22 │  * <p>{@link AccountLocking}'s own Javadoc states the deadlock the rule prevents, and it is
 23 │  * not restated here. What matters for these tests is that the property asserted below — the
 24 │  * lower ID first, whichever role it holds — is the entire premise that argument stands on.
 25 │  * Ticket 13 is where two real threads demonstrate the conclusion; this is what is provable
 26 │  * without them.
 27 │  *
 28 │  * <p>The repository is a recorder rather than a database, because the order two
 29 │  * {@code select … for update} statements were issued in is not something the statements
 30 │  * themselves say — they are the same SQL with a different bound parameter.
 31 │  * {@link AccountLockIsASelectForUpdateTest} is the half that needs a real database.
 32 │  */
 33 │ class AccountsLockInAscendingIdOrderTest {
 34 │ 
 35 │ 	private static final long LOWER_ID = 5L;
 36 │ 	private static final long HIGHER_ID = 9L;
 37 │ 
 38 │ 	private final RecordingAccountRepository accounts = new RecordingAccountRepository()
 39 │ 			.holding(LOWER_ID, new Money(100_00L, Currency.EUR))
 40 │ 			.holding(HIGHER_ID, new Money(250_00L, Currency.USD));
 41 │ 
 42 │ 	private final AccountLocking locking = new AccountLocking(accounts);
 43 │ 
 44 │ 	@Test
 45 │ 	@DisplayName("the lower Account ID is locked first when it is the source")
 46 │ 	void locksTheLowerIdFirstWhenItIsTheSource() {
 47 │ 		locking.lockForTransfer(LOWER_ID, HIGHER_ID);
 48 │ 
 49 │ 		assertThat(accounts.lockedInOrder).containsExactly(LOWER_ID, HIGHER_ID);
 50 │ 	}
 51 │ 
 52 │ 	/** The same order, from the request a role-ordered acquisition would reverse. */
 53 │ 	@Test
 54 │ 	@DisplayName("the lower Account ID is locked first when it is the destination")
 55 │ 	void locksTheLowerIdFirstWhenItIsTheDestination() {
 56 │ 		locking.lockForTransfer(HIGHER_ID, LOWER_ID);
 57 │ 
 58 │ 		assertThat(accounts.lockedInOrder).containsExactly(LOWER_ID, HIGHER_ID);
 59 │ 	}
 60 │ 
 61 │ 	/**
 62 │ 	 * Acquisition order is not the caller's problem: the pair comes back named by role, so
 63 │ 	 * nothing downstream has to remember which of the two the lock order happened to put
 64 │ 	 * first.
 65 │ 	 */
 66 │ 	@Test
 67 │ 	@DisplayName("the locked Accounts come back named by their role in the Transfer")
 68 │ 	void handsBackTheAccountsByTheirRoleInTheTransfer() {
 69 │ 		LockedAccounts locked = locking.lockForTransfer(HIGHER_ID, LOWER_ID);
 70 │ 
 71 │ 		assertThat(locked.source().getCurrency()).isEqualTo(Currency.USD);
 72 │ 		assertThat(locked.destination().getCurrency()).isEqualTo(Currency.EUR);
 73 │ 	}
 74 │ 
 75 │ 	/**
 76 │ 	 * Design decision 6 refuses a self-Transfer with a {@code 422} before locking, and
 77 │ 	 * ticket 14 owns that answer. This is the backstop under it: a caller that skipped the
 78 │ 	 * refusal gets an error rather than a pair whose two sides are one row.
 79 │ 	 */
 80 │ 	@Test
 81 │ 	@DisplayName("an Account on both sides of the Transfer is refused rather than locked twice")
 82 │ 	void refusesATransferWithOneAccountOnBothSides() {
 83 │ 		assertThatThrownBy(() -> locking.lockForTransfer(LOWER_ID, LOWER_ID))
 84 │ 				.isInstanceOf(IllegalArgumentException.class)
 85 │ 				.hasMessageContaining(String.valueOf(LOWER_ID));
 86 │ 
 87 │ 		assertThat(accounts.lockedInOrder).isEmpty();
 88 │ 	}
 89 │ 
 90 │ 	@Test
 91 │ 	@DisplayName("an Account that is not there is reported by ID")
 92 │ 	void namesTheAccountItCouldNotFind() {
 93 │ 		long missingId = 404L;
 94 │ 
 95 │ 		assertThatThrownBy(() -> locking.lockForTransfer(LOWER_ID, missingId))
 96 │ 				.isInstanceOf(UnknownAccountException.class)
 97 │ 				.extracting(thrown -> ((UnknownAccountException) thrown).getAccountId())
 98 │ 				.isEqualTo(missingId);
 99 │ 	}
100 │ 
101 │ 	/**
102 │ 	 * Records the order it is asked to lock in, which is the one thing a database cannot
103 │ 	 * report: both statements are the same SQL with a different bound parameter.
104 │ 	 *
105 │ 	 * <p>The three refusals below are the read and write paths tickets 09 and 10 added to
106 │ 	 * {@link AccountRepository}. Reaching one of them from {@link AccountLocking} would be
107 │ 	 * a bug — the locked path has no business listing or saving — so failing loudly is the
108 │ 	 * useful answer, and a silent stub would let that bug pass this test.
109 │ 	 */
110 │ 	private static final class RecordingAccountRepository implements AccountRepository {
111 │ 
112 │ 		private final List<Long> lockedInOrder = new ArrayList<>();
113 │ 		private final Map<Long, Account> rows = new HashMap<>();
114 │ 
115 │ 		private RecordingAccountRepository holding(long accountId, Money openingBalance) {
116 │ 			rows.put(accountId, new Account(openingBalance));
117 │ 			return this;
118 │ 		}
119 │ 
120 │ 		@Override
121 │ 		public Optional<Account> findAndLockById(long accountId) {
122 │ 			lockedInOrder.add(accountId);
123 │ 			return Optional.ofNullable(rows.get(accountId));
124 │ 		}
125 │ 
126 │ 		@Override
127 │ 		public List<Account> findAllByOrderByIdAsc() {
128 │ 			throw new UnsupportedOperationException("the locked path does not list accounts");
129 │ 		}
130 │ 
131 │ 		@Override
132 │ 		public Account save(Account account) {
133 │ 			throw new UnsupportedOperationException("the locked path does not open accounts");
134 │ 		}
135 │ 
136 │ 		@Override
137 │ 		public List<Account> saveAll(Iterable<Account> accounts) {
138 │ 			throw new UnsupportedOperationException("the locked path does not seed accounts");
139 │ 		}
140 │ 	}
141 │ }
