  1 │ package hu.bankmonitor.payments.accounts;
  2 │ 
  3 │ import hu.bankmonitor.payments.common.Currency;
  4 │ import hu.bankmonitor.payments.common.Money;
  5 │ import org.hibernate.cfg.AvailableSettings;
  6 │ import org.hibernate.resource.jdbc.spi.StatementInspector;
  7 │ import org.junit.jupiter.api.DisplayName;
  8 │ import org.junit.jupiter.api.Test;
  9 │ import org.springframework.beans.factory.annotation.Autowired;
 10 │ import org.springframework.boot.data.jpa.test.autoconfigure.DataJpaTest;
 11 │ import org.springframework.boot.jpa.test.autoconfigure.TestEntityManager;
 12 │ import org.springframework.boot.test.context.TestConfiguration;
 13 │ import org.springframework.boot.hibernate.autoconfigure.HibernatePropertiesCustomizer;
 14 │ import org.springframework.context.annotation.Import;
 15 │ import org.springframework.test.context.TestPropertySource;
 16 │ import org.springframework.transaction.IllegalTransactionStateException;
 17 │ import org.springframework.transaction.annotation.Propagation;
 18 │ import org.springframework.transaction.annotation.Transactional;
 19 │ 
 20 │ import java.util.List;
 21 │ import java.util.Locale;
 22 │ import java.util.Map;
 23 │ import java.util.concurrent.CopyOnWriteArrayList;
 24 │ 
 25 │ import static org.assertj.core.api.Assertions.assertThat;
 26 │ import static org.assertj.core.api.Assertions.assertThatThrownBy;
 27 │ 
 28 │ /**
 29 │  * The half of design decision 6 that only a database can answer: that
 30 │  * {@link AccountLocking} really does take row locks, rather than reading two rows under an
 31 │  * annotation nobody has checked.
 32 │  *
 33 │  * <p>The statements are read out of Hibernate rather than inferred from the mapping, for
 34 │  * the same reason {@code AccountHoldsTwoFiguresInOneCurrencyTest} reads its columns in
 35 │  * SQL: an assertion phrased through the thing under test would agree with whatever that
 36 │  * thing decided to do. What is asserted is the shape the deadlock argument depends on —
 37 │  * one {@code select … for update} per Account, so that "which lock was taken first" is a
 38 │  * question the wire has an answer to at all.
 39 │  *
 40 │  * <p>Which of the two comes first is not decidable here, because both statements are the
 41 │  * same SQL with a different bound parameter;
 42 │  * {@link AccountsLockInAscendingIdOrderTest} is where that half lives.
 43 │  */
 44 │ @DataJpaTest
 45 │ @TestPropertySource(properties =
 46 │ 		// The application's own setting; the slice would otherwise export the schema itself.
 47 │ 		"spring.jpa.hibernate.ddl-auto=validate")
 48 │ @Import(AccountLocking.class)
 49 │ class AccountLockIsASelectForUpdateTest {
 50 │ 
 51 │ 	@Autowired
 52 │ 	private TestEntityManager entityManager;
 53 │ 
 54 │ 	@Autowired
 55 │ 	private AccountLocking locking;
 56 │ 
 57 │ 	@Autowired
 58 │ 	private CapturingStatementInspector statements;
 59 │ 
 60 │ 	@Test
 61 │ 	@DisplayName("locking a Transfer's Accounts issues one select-for-update per Account")
 62 │ 	void takesARowLockOnEachAccountSeparately() {
 63 │ 		long first = openAccount(new Money(400_00L, Currency.EUR));
 64 │ 		long second = openAccount(new Money(700_00L, Currency.USD));
 65 │ 		entityManager.flush();
 66 │ 		entityManager.clear();
 67 │ 		statements.forget();
 68 │ 
 69 │ 		locking.lockForTransfer(second, first);
 70 │ 
 71 │ 		assertThat(statements.captured())
 72 │ 				.hasSize(2)
 73 │ 				.allSatisfy(sql -> assertThat(sql)
 74 │ 						.contains("from accounts")
 75 │ 						.contains("where")
 76 │ 						.endsWith("for update"));
 77 │ 	}
 78 │ 
 79 │ 	/**
 80 │ 	 * The lock has to outlive the read for the balance check that follows it to mean
 81 │ 	 * anything, so the operation refuses to run where nothing would hold it. Mandatory
 82 │ 	 * propagation is what turns a caller that forgot {@code @Transactional} into a failure
 83 │ 	 * here rather than a race in production.
 84 │ 	 *
 85 │ 	 * <p>{@code NOT_SUPPORTED} is what takes the transaction {@code @DataJpaTest} would
 86 │ 	 * otherwise wrap this method in away again. No Accounts are opened for it because it
 87 │ 	 * must not reach the table at all.
 88 │ 	 */
 89 │ 	@Test
 90 │ 	@Transactional(propagation = Propagation.NOT_SUPPORTED)
 91 │ 	@DisplayName("locking outside a transaction is refused rather than quietly useless")
 92 │ 	void refusesToLockWithNoTransactionToHoldTheLock() {
 93 │ 		assertThatThrownBy(() -> locking.lockForTransfer(1L, 2L))
 94 │ 				.isInstanceOf(IllegalTransactionStateException.class);
 95 │ 	}
 96 │ 
 97 │ 	private long openAccount(Money openingBalance) {
 98 │ 		return entityManager.persistAndGetId(new Account(openingBalance), Long.class);
 99 │ 	}
100 │ 
101 │ 	/**
102 │ 	 * Hibernate hands every statement to a {@link StatementInspector} on its way to the
103 │ 	 * driver, which is the only place the {@code for update} suffix is visible: it is
104 │ 	 * appended by the dialect, so neither the entity nor the repository method mentions
105 │ 	 * it.
106 │ 	 */
107 │ 	@TestConfiguration(proxyBeanMethods = false)
108 │ 	static class CapturingStatementInspector implements HibernatePropertiesCustomizer, StatementInspector {
109 │ 
110 │ 		private final List<String> statements = new CopyOnWriteArrayList<>();
111 │ 
112 │ 		@Override
113 │ 		public void customize(Map<String, Object> hibernateProperties) {
114 │ 			hibernateProperties.put(AvailableSettings.STATEMENT_INSPECTOR, this);
115 │ 		}
116 │ 
117 │ 		@Override
118 │ 		public String inspect(String sql) {
119 │ 			statements.add(sql.toLowerCase(Locale.ROOT).trim());
120 │ 			return sql;
121 │ 		}
122 │ 
123 │ 		List<String> captured() {
124 │ 			return List.copyOf(statements);
125 │ 		}
126 │ 
127 │ 		/** The context is cached across tests, so the inspector outlives any one of them. */
128 │ 		void forget() {
129 │ 			statements.clear();
130 │ 		}
131 │ 	}
132 │ }
