  2 │ 
  3 │ import hu.bankmonitor.payments.common.Currency;
  4 │ import hu.bankmonitor.payments.common.Money;
  5 │ import org.junit.jupiter.api.DisplayName;
  6 │ import org.junit.jupiter.api.Test;
  7 │ import org.springframework.beans.factory.annotation.Autowired;
  8 │ import org.springframework.boot.data.jpa.test.autoconfigure.DataJpaTest;
  9 │ import org.springframework.boot.jpa.test.autoconfigure.TestEntityManager;
 10 │ import org.springframework.test.context.TestPropertySource;
 11 │ 
 12 │ import java.util.List;
 13 │ 
 14 │ import static org.assertj.core.api.Assertions.assertThat;
 15 │ import static org.assertj.core.api.Assertions.assertThatThrownBy;
 16 │ 
 17 │ /**
 18 │  * An {@link Account}'s two Money figures reach four columns of their own, and the table
 19 │  * refuses the rows the entity has no way to produce.
 20 │  *
 21 │  * <p>Two embeddables of the same type is the case the implicit naming strategy cannot
 22 │  * serve: it names an embeddable's columns after the component's own fields and not after
 23 │  * the field holding it, so both {@code Money} figures would ask for {@code minor_units}
 24 │  * and {@code currency}. The {@code @AttributeOverride}s on the entity are what keep them
 25 │  * apart, and the column names asserted here are the ones {@code V1__accounts.sql} was
 26 │  * written to match. Design decision 29 has the mapping story.
 27 │  *
 28 │  * <p>Startup is half of every assertion below: {@code validate} has already compared the
 29 │  * entity against the migration by the time any method runs.
 30 │  */
 31 │ @DataJpaTest
 32 │ @TestPropertySource(properties =
 33 │ 		// The application's own setting, restated because the claim above rests on it.
 34 │ 		"spring.jpa.hibernate.ddl-auto=validate")
 35 │ class AccountHoldsTwoFiguresInOneCurrencyTest {
 36 │ 
 37 │ 	@Autowired
 38 │ 	private TestEntityManager entityManager;
 39 │ 
 40 │ 	@Test
 41 │ 	@DisplayName("a new Account holds its opening balance with nothing reserved against it")
 42 │ 	void opensWithNothingReservedAgainstIt() {
 43 │ 		Money opening = new Money(250_00L, Currency.EUR);
 44 │ 
 45 │ 		Long id = entityManager.persistAndGetId(new Account(opening), Long.class);
 46 │ 		entityManager.flush();
 47 │ 		entityManager.clear();
 48 │ 
 49 │ 		Account reopened = entityManager.find(Account.class, id);
 50 │ 
 51 │ 		assertThat(reopened.getBalance()).isEqualTo(opening);
 52 │ 		assertThat(reopened.getReservedAmount()).isEqualTo(Money.zero(Currency.EUR));
 53 │ 		assertThat(reopened.getAvailableBalance()).isEqualTo(opening);
 54 │ 		assertThat(reopened.getCurrency()).isEqualTo(Currency.EUR);
 55 │ 	}
 56 │ 
 57 │ 	/**
 58 │ 	 * Read in SQL rather than through Hibernate, so this asserts what is in the database
 59 │ 	 * rather than what the mapping is willing to say about it — a round trip through the
 60 │ 	 * same mapping would agree with itself whichever columns it chose.
 61 │ 	 */
 62 │ 	@Test
 63 │ 	@DisplayName("the balance and the Reserved Amount each get their own pair of columns")
 64 │ 	void keepsTheTwoFiguresInColumnsOfTheirOwn() {
 65 │ 		entityManager.persistAndFlush(new Account(new Money(900_00L, Currency.USD)));
 66 │ 		entityManager.clear();
 67 │ 
 68 │ 		@SuppressWarnings("unchecked")
 69 │ 		List<Object[]> rows = entityManager.getEntityManager().createNativeQuery("""
 70 │ 				SELECT balance_minor_units, balance_currency,
 71 │ 				       reserved_amount_minor_units, reserved_amount_currency
 72 │ 				FROM accounts
 73 │ 				""").getResultList();
 74 │ 
 75 │ 		assertThat(rows).hasSize(1);
 76 │ 		assertThat(((Number) rows.getFirst()[0]).longValue()).isEqualTo(900_00L);
 77 │ 		assertThat(rows.getFirst()[1]).hasToString("USD");
 78 │ 		assertThat(((Number) rows.getFirst()[2]).longValue()).isZero();
 79 │ 		assertThat(rows.getFirst()[3]).hasToString("USD");
 80 │ 	}
 81 │ 
 82 │ 	/**
 83 │ 	 * The other direction, and the only one that can reach a non-zero Reserved Amount
 84 │ 	 * today: raising it is ticket 13's reservation, so until that lands the row is written
 85 │ 	 * in SQL. HUF because its Minor Units are not hundredths, so a figure that survived a
 86 │ 	 * stray division by a hundred would not read back equal.
 87 │ 	 */
 88 │ 	@Test
 89 │ 	@DisplayName("money reserved against an Account comes back out of its Available Balance")
 90 │ 	void subtractsAReservationFromTheAvailableBalance() {
 91 │ 		insertAccount(90_000L, "HUF", 25_000L, "HUF");
 92 │ 		entityManager.clear();
 93 │ 
 94 │ 		Account account = entityManager.find(Account.class, onlyAccountId());
 95 │ 
 96 │ 		assertThat(account.getBalance()).isEqualTo(new Money(90_000L, Currency.HUF));
 97 │ 		assertThat(account.getReservedAmount()).isEqualTo(new Money(25_000L, Currency.HUF));
 98 │ 		assertThat(account.getAvailableBalance()).isEqualTo(new Money(65_000L, Currency.HUF));
 99 │ 	}
100 │ 
101 │ 	/** The backstop under ticket 13's overdraft check, not a replacement for it. */
102 │ 	@Test
103 │ 	@DisplayName("the table refuses a Reserved Amount larger than the balance it is held against")
104 │ 	void refusesToReserveMoreThanTheAccountHolds() {
105 │ 		assertThatThrownBy(() -> insertAccount(100L, "EUR", 101L, "EUR"))
106 │ 				.hasStackTraceContaining("ACCOUNTS_RESERVED_WITHIN_BALANCE");
107 │ 	}
108 │ 
109 │ 	@Test
110 │ 	@DisplayName("the table refuses an Account whose two figures are in different currencies")
111 │ 	void refusesAnAccountDenominatedInTwoCurrencies() {
112 │ 		assertThatThrownBy(() -> insertAccount(100L, "EUR", 0L, "USD"))
113 │ 				.hasStackTraceContaining("ACCOUNTS_ONE_CURRENCY");
114 │ 	}
115 │ 
116 │ 	private void insertAccount(long balanceMinorUnits, String balanceCurrency,
117 │ 			long reservedMinorUnits, String reservedCurrency) {
118 │ 		entityManager.getEntityManager().createNativeQuery("""
119 │ 						INSERT INTO accounts (balance_minor_units, balance_currency,
120 │ 						                      reserved_amount_minor_units, reserved_amount_currency)
121 │ 						VALUES (?, ?, ?, ?)
122 │ 						""")
123 │ 				.setParameter(1, balanceMinorUnits)
124 │ 				.setParameter(2, balanceCurrency)
125 │ 				.setParameter(3, reservedMinorUnits)
126 │ 				.setParameter(4, reservedCurrency)
127 │ 				.executeUpdate();
128 │ 	}
129 │ 
130 │ 	/** The identity column picks the value, so the row has to say which one it got. */
131 │ 	private Long onlyAccountId() {
132 │ 		return ((Number) entityManager.getEntityManager()
133 │ 				.createNativeQuery("SELECT id FROM accounts")
134 │ 				.getSingleResult()).longValue();
135 │ 	}
136 │ }

